SELECT m.id, m.provider_id, m.global_id, m.thread_id, m.provider_thread_id, m.replying_to_id, m.link_id, m.provider_history_id, m.internal_date_ts, m.snippet, m.size_estimate, m.subject, m.from_name, m.from_contact_id, m.sent_at, m.has_attachments, m.is_read, m.is_starred, m.is_sent, m.is_draft, m.body_text, m.body_html_sanitized, m.body_macro, m.headers_jsonb, m.created_at, m.updated_at FROM email_messages m JOIN email_scheduled_messages sm ON m.id = sm.message_id WHERE m.link_id = $1 AND m.is_draft = true AND m.is_sent = false AND sm.sent = false ORDER BY m.created_at DESC LIMIT $2 OFFSET $3
